function PVPArenaRankRewardDialog:RefreshUI()
    ---@type BaseSetting
    local setting = CfUtils.GetCf(AutoIds.IdSetting1042, "PVPArenaRankRewardVo")
    ---@type PVPArenaRankRewardVo[]
    self.rankRewardVos = setting:GetAll()
    table.sort(self.rankRewardVos, function(a, b)
        return a.refId > b.refId
    end)

    local count = table.count(self.rankRewardVos)
    local LoopList = self.LoopList
    if not LoopList.IsListViewInit then
        LoopList:InitListView(count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(LoopList, count)
    end
end

function PVPArenaRankRewardDialog:OnGetItemByIndex(listView, idx)
